mapper.update:
UPDATE users
username = #{username}, password = #{password}, phone = #{phone}, profile_image = #{profileImage}, role = #{role}, status = #{userAccountStatus}, refresh = #{refreshToken}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}

mapper.select:
SELECT user_id, username, email
FROM users
WHERE username = #{username}
AND email = #{email}
